import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import fs from 'node:fs';
import {handleApi} from '../worker/account-api.js';

const sql=new DatabaseSync(':memory:');sql.exec('PRAGMA foreign_keys=ON');
for(const file of fs.readdirSync(new URL('../drizzle/',import.meta.url)).filter(file=>file.endsWith('.sql')).sort())sql.exec(fs.readFileSync(new URL('../drizzle/'+file,import.meta.url),'utf8'));
let beforeBatch=null,failBatchAt=-1;
class Statement{constructor(query,args=[]){this.query=query;this.args=args;}bind(...args){return new Statement(this.query,args);}async first(){return sql.prepare(this.query).get(...this.args)||null;}async all(){return {results:sql.prepare(this.query).all(...this.args)};}async run(){return {meta:{changes:sql.prepare(this.query).run(...this.args).changes}};}}
let chain=Promise.resolve();const DB={prepare:q=>new Statement(q),batch(statements){const next=chain.then(()=>{if(beforeBatch){const hook=beforeBatch;beforeBatch=null;hook();}sql.exec('BEGIN');try{const out=statements.map((statement,index)=>{if(index===failBatchAt){failBatchAt=-1;throw Error('Injected storage failure');}return {meta:{changes:sql.prepare(statement.query).run(...statement.args).changes}};});sql.exec('COMMIT');return out;}catch(error){sql.exec('ROLLBACK');throw error;}});chain=next.catch(()=>{});return next;}};
async function api(actor,path,method='GET',body){const result=await handleApi(new Request('https://test.chatgpt.site/api'+path,{method,headers:{...(actor?{'oai-authenticated-user-id':actor,'oai-authenticated-user-email':actor+'@example.test','X-UK-Account-ID':actor}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined}),{DB});return {status:result.status,...await result.json()};}
for(const actor of ['owner','source','editor','viewer','outsider','pending'])assert.equal((await api(actor,'/account')).status,200);
sql.prepare('INSERT INTO local_credentials(user_id,login_id,login_key,password_salt,password_hash,password_iterations,password_version,created_at,updated_at) VALUES(?,?,?,?,?,100000,1,?,?)').run('source','로비_참가자','로비_참가자','fixture-salt-never-public','fixture-hash-never-public','2026-11-01','2026-11-01');
const clone=x=>structuredClone(x),strip=x=>Array.isArray(x)?x.map(strip):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).filter(([key])=>!['privateNotes','private_notes','battleRecords'].includes(key)).map(([key,value])=>[key,strip(value)])):x;
const doc=actor=>{const row=sql.prepare('SELECT revision,state FROM documents WHERE user_id=?').get(actor);return {revision:row.revision,state:JSON.parse(row.state)};};
const writeDoc=(actor,state)=>sql.prepare('INSERT INTO documents(user_id,revision,state,updated_at) VALUES(?,1,?,?) ON CONFLICT(user_id) DO UPDATE SET revision=1,state=excluded.state').run(actor,JSON.stringify(state),'2026-11-01');
let serial=0,keySerial=0;
function fixture(){const id='lobby-fixture-'+(++serial),requestId='lobby-request-'+serial,foreign='enrolled-'+requestId;
 const gang=name=>({id:'same',name,edition:'N26',credits:100,reputation:1,fighters:[{id:'fighter',name:name+' Fighter',status:'Active',xp:5,privateNotes:'private fighter note'}],tactics:[],stash:[],privateNotes:'private '+name,battleRecords:[{id:'private-ledger',result:'Win',opponent:'Name only'}]});
 const host=gang('Host'),source=gang('Source'),campaign={id,name:'Lobby campaign '+serial,edition:'N26',phase:'Active',currentCycle:1,campaignTypeId:'official-003-campaign-necromunda-campaign',members:[{id:'host-member',gangId:'same',player:'Host'},{id:'source-member',gangId:foreign,player:'Source',userId:'source',ownerId:'source',sourceGangId:'same',enrollmentRequestId:requestId}],territories:[{id:'stake',name:'Gambling Den',territoryId:'official-003-territory-gambling-den',gangId:'',ruined:false}],sessions:[{id:'legacy-session',stage:'completed',status:'Completed',participants:[]}],battles:[{id:'legacy-battle',status:'Played',name:'Retained legacy record',notes:'retained legacy notes',participants:[]}],activity:[],privateNotes:'private campaign'};
 for(const [actor,state]of Object.entries({owner:{gangs:[host],campaigns:[clone(campaign)]},source:{gangs:[source],campaigns:[]},editor:{gangs:[{...gang('Unrelated local original'),id:'unrelated'}],campaigns:[]},viewer:{gangs:[],campaigns:[]},outsider:{gangs:[],campaigns:[]},pending:{gangs:[gang('Pending')],campaigns:[]}}))writeDoc(actor,state);
 const snapshot={campaign:strip(campaign),gangs:[strip(host),{...strip(source),id:foreign,sourceGangId:'same',sourceOwnerId:'source',remoteOwnerId:'source',remoteReadOnly:true,enrollmentRequestId:requestId}]};
 sql.prepare('INSERT INTO shared_campaigns(id,owner_id,name,snapshot,revision,updated_at) VALUES(?,?,?,?,1,?)').run(id,'owner',campaign.name,JSON.stringify(snapshot),'2026-11-01');
 for(const [actor,role,status]of [['source','viewer','accepted'],['editor','editor','accepted'],['viewer','viewer','accepted'],['pending','viewer','pending']])sql.prepare('INSERT INTO campaign_access(campaign_id,user_id,role,status,invited_at) VALUES(?,?,?,?,?)').run(id,actor,role,status,'2026-11-01');
 sql.prepare("INSERT INTO campaign_join_requests(id,campaign_id,user_id,gang_id,gang_name,gang_snapshot,source_revision,message,status,created_at,updated_at) VALUES(?,?,?,?,?,?,1,'','approved',?,?)").run(requestId,id,'source','same','Source',JSON.stringify(strip(source)),'2026-11-01','2026-11-01');
 return {id,foreign,requestId,snapshot};}
const path=f=>'/campaigns/'+f.id+'/lobby',read=f=>JSON.parse(sql.prepare('SELECT snapshot FROM shared_campaigns WHERE id=?').get(f.id).snapshot),revision=f=>sql.prepare('SELECT revision FROM shared_campaigns WHERE id=?').get(f.id).revision;
async function create(f,actor='owner',extra={}){const result=await api(actor,path(f),'POST',{operationKey:'create-'+(++keySerial),ownGangId:actor==='source'?f.foreign:'same',targetUserId:actor==='source'?'owner':'source',targetGangId:actor==='source'?'same':f.foreign,setup:{territoryId:'stake',deploymentId:'deployment-fixture',objectiveId:'objective-fixture',crewSelectionId:'crew-fixture',scenarioName:'Campaign match'},...extra});assert.equal(result.status,201,result.error);assert(result.room?.id);return result.room;}
async function action(f,room,actor,name,extra={},expected=200){const result=await api(actor,path(f)+'/'+room.id,'POST',{action:name,revision:room.revision,operationKey:name+'-'+(++keySerial),...extra});assert.equal(result.status,expected,name+': '+result.error);return result.room||result;}
async function enter(f){const invited=await create(f);let room=await action(f,invited,'source','accept');assert.equal(room.status,'preparing');for(const actor of ['owner','source'])room=await action(f,room,actor,'prepare',{preparation:{fighterIds:['fighter'],sideJobId:'',tacticIds:[],note:''}});return room;}
async function battle(f,{sideJobs=false}={}){let room=await enter(f);room=await action(f,room,'owner','prepare',{preparation:{fighterIds:['fighter'],sideJobId:sideJobs?'official-003-sidejob-the-package':'',tacticIds:[],note:'Host preparation'}});room=await action(f,room,'source','prepare',{preparation:{fighterIds:['fighter'],sideJobId:sideJobs?'official-003-sidejob-stitch-em-up':'',tacticIds:[],note:'Source preparation'}});room=await action(f,room,'owner','ready',{ready:true});room=await action(f,room,'source','ready',{ready:true});room=await action(f,room,'owner','start');assert.equal(room.status,'battle');return room;}
function originals(){return {owner:clone(doc('owner').state.gangs),source:clone(doc('source').state.gangs)};}
function assertOriginals(before){assert.deepEqual(doc('owner').state.gangs,before.owner);assert.deepEqual(doc('source').state.gangs,before.source);}

// Only accepted campaign accounts are listed, and source provenance defeats local ID collisions.
let f=fixture(),snapshot,result=await api('source',path(f));assert.equal(result.status,200,result.error);assert.equal(result.actorId,'source');assert(result.players.some(player=>player.userId==='source'&&player.gangs.some(gang=>gang.id===f.foreign)));assert.equal(result.players.find(player=>player.userId==='source').loginId,'로비_참가자');assert.equal(JSON.stringify(result).includes('fixture-salt-never-public'),false);assert.equal(JSON.stringify(result).includes('fixture-hash-never-public'),false);assert.equal(JSON.stringify(result).includes('password_'),false);assert(result.players.some(player=>player.userId==='owner'&&player.gangs.some(gang=>gang.id==='same')));assert(!result.players.some(player=>player.userId==='pending'));assert.equal(JSON.stringify(result).includes('private-ledger'),false);assert.equal(JSON.stringify(result).includes('private fighter note'),false);assert.equal(JSON.stringify(result).includes('@example.test'),false);
for(const actor of ['outsider','pending',null]){result=await api(actor,path(f));assert([401,403].includes(result.status),String(result.status));}
for(const actor of ['editor','viewer']){result=await api(actor,path(f),'POST',{operationKey:'forged-'+actor,ownGangId:'same',targetUserId:'source',targetGangId:f.foreign});assert.equal(result.status,403,result.error);}
for(const targetUserId of ['owner','outsider','pending','viewer']){result=await api('owner',path(f),'POST',{operationKey:'invalid-target-'+targetUserId,ownGangId:'same',targetUserId});assert([400,403,409].includes(result.status),targetUserId+': '+result.status);}
result=await api('source',path(f),'POST',{operationKey:'source-claims-host',ownGangId:'same',targetUserId:'owner',targetGangId:'same'});assert.equal(result.status,403,result.error);
console.log('PASS lobby access and approved canonical gang ownership are bound to actual accounts');

// The recipient joins the same durable room; neither account can edit the other's preparation.
f=fixture();let before=originals(),room=await create(f);assert.equal(room.status,'invited');assert.equal(room.hostId,'owner');assert.equal(room.guestId,'source');assert.equal(room.participants.find(p=>p.userId==='source').loginId,'로비_참가자');assert.equal(JSON.stringify(room).includes('fixture-hash-never-public'),false);assert.equal((await api('source',path(f)+'/'+room.id)).room.id,room.id);assert.equal((await api('outsider',path(f)+'/'+room.id)).status,403);const hostPresence=room.participants.find(p=>p.userId==='owner').presenceAt;const heartbeat=await api('source',path(f)+'/'+room.id,'POST',{action:'heartbeat',userId:'owner',presenceAt:'2999-01-01T00:00:00Z'});assert.equal(heartbeat.status,200,heartbeat.error);assert.equal(heartbeat.room.revision,room.revision);assert.equal(heartbeat.room.participants.find(p=>p.userId==='owner').presenceAt,hostPresence);assert(heartbeat.room.participants.find(p=>p.userId==='source').presenceAt.startsWith(new Date().toISOString().slice(0,10)));assert.equal(JSON.stringify(heartbeat).includes('2999'),false);
result=await api('editor',path(f)+'/'+room.id,'POST',{action:'accept',revision:room.revision,operationKey:'editor-accept'});assert.equal(result.status,403,result.error);await action(f,room,'owner','accept',{},403);room=await action(f,room,'source','accept');
const guestPreparation=clone(room.participants.find(p=>p.userId==='source').preparation);result=await api('owner',path(f)+'/'+room.id,'POST',{action:'prepare',revision:room.revision,operationKey:'forge-other-preparation',preparation:{fighterIds:['fighter'],sideJobId:'',tacticIds:[],note:'My own note'},userId:'source',participants:[{userId:'source',ready:true}]});assert.equal(result.status,403,result.error);room=(await api('source',path(f)+'/'+room.id)).room;assert.deepEqual(room.participants.find(p=>p.userId==='source').preparation,guestPreparation);assert.equal(room.participants.find(p=>p.userId==='source').ready,false);
await action(f,room,'source','prepare',{preparation:{fighterIds:['not-my-fighter'],sideJobId:'',tacticIds:[],note:''}},400);assertOriginals(before);
console.log('PASS account invitation, recipient-only entry and own preparation preserve opponent and original records');

// Optimistic state and idempotent operation keys avoid duplicate rooms/actions under ambiguous retries.
f=fixture();const createBody={operationKey:'stable-create',ownGangId:'same',targetUserId:'source',targetGangId:f.foreign,setup:{territoryId:'stake'}};result=await api('owner',path(f),'POST',createBody);assert.equal(result.status,201,result.error);room=result.room;let replay=await api('owner',path(f),'POST',createBody);assert.equal(replay.status,200,replay.error);assert.equal(replay.room.id,room.id);assert.equal((await api('owner',path(f))).rooms.length,1);result=await api('owner',path(f),'POST',{...createBody,setup:{territoryId:''}});assert.equal(result.status,409,result.error);
const acceptBody={action:'accept',revision:room.revision,operationKey:'stable-accept'};result=await api('source',path(f)+'/'+room.id,'POST',acceptBody);assert.equal(result.status,200,result.error);room=result.room;replay=await api('source',path(f)+'/'+room.id,'POST',acceptBody);assert.equal(replay.status,200,replay.error);assert.equal(replay.room.revision,room.revision);result=await api('source',path(f)+'/'+room.id,'POST',{...acceptBody,action:'decline'});assert.equal(result.status,409,result.error);await action(f,{...room,revision:room.revision-1},'owner','ready',{ready:true},409);
console.log('PASS durable room and action retries are idempotent while stale or reused-different requests are rejected');

// Both players prepare themselves, and a preparation/setup edit clears readiness before the shared start.
f=fixture();room=await enter(f);await action(f,room,'owner','start',{},409);room=await action(f,room,'owner','ready',{ready:true});assert.equal(room.participants.find(p=>p.userId==='owner').ready,true);room=await action(f,room,'owner','prepare',{preparation:{fighterIds:['fighter'],sideJobId:'',tacticIds:[],note:'Changed preparation'}});assert.equal(room.participants.find(p=>p.userId==='owner').ready,false);room=await action(f,room,'owner','ready',{ready:true});room=await action(f,room,'source','ready',{ready:true});await action(f,room,'source','setup',{setup:{territoryId:''}},403);room=await action(f,room,'owner','setup',{setup:{territoryId:'stake',scenarioName:'Updated match'}});assert(room.participants.every(p=>!p.ready));
room=await action(f,room,'owner','ready',{ready:true});const simultaneous=await Promise.all([api('source',path(f)+'/'+room.id,'POST',{action:'ready',ready:true,revision:room.revision,operationKey:'sim-ready-source'}),api('owner',path(f)+'/'+room.id,'POST',{action:'prepare',preparation:{fighterIds:['fighter'],note:'Concurrent edit'},revision:room.revision,operationKey:'sim-prepare-host'})]);assert.equal(simultaneous.filter(r=>r.status===200).length,1);assert.equal(simultaneous.filter(r=>r.status===409).length,1);room=(await api('owner',path(f)+'/'+room.id)).room;assert.equal(read(f).campaign.sessions.length,1);
f=fixture();room=await enter(f);room=await action(f,room,'owner','ready',{ready:true});room=await action(f,room,'source','ready',{ready:true});const changedSource=doc('source');changedSource.state.gangs[0].fighters[0].status='Dead';sql.prepare('UPDATE documents SET state=?,revision=revision+1 WHERE user_id=?').run(JSON.stringify(changedSource.state),'source');await action(f,room,'owner','start',{},409);assert.equal(read(f).campaign.sessions.length,1);
console.log('PASS preparation and setup clear readiness, and concurrent state writes cannot start conflicting games');

// Independent seat revisions let both accounts prepare naturally without overwriting one another.
f=fixture();room=await enter(f);const pRevision=(value,actor)=>value.participants.find(p=>p.userId===actor).revision;
assert(Number.isSafeInteger(pRevision(room,'owner'))&&pRevision(room,'owner')>0);const commonRevision=room.revision,ownerCounter=pRevision(room,'owner'),sourceCounter=pRevision(room,'source');
const ownPrepareBodies=['owner','source'].map(actor=>({action:'prepare',revision:commonRevision,participantRevision:pRevision(room,actor),operationKey:'natural-prepare-'+actor,preparation:{fighterIds:['fighter'],sideJobId:'',tacticIds:[],note:'Prepared by '+actor}}));
let parallel=await Promise.all(['owner','source'].map((actor,index)=>api(actor,path(f)+'/'+room.id,'POST',ownPrepareBodies[index])));assert(parallel.every(value=>value.status===200),JSON.stringify(parallel.map(value=>({status:value.status,error:value.error}))));room=(await api('owner',path(f)+'/'+room.id)).room;assert.equal(room.revision,commonRevision+2);assert.equal(pRevision(room,'owner'),ownerCounter+1);assert.equal(pRevision(room,'source'),sourceCounter+1);assert.equal(room.participants.find(p=>p.userId==='owner').preparation.note,'Prepared by owner');assert.equal(room.participants.find(p=>p.userId==='source').preparation.note,'Prepared by source');
const sameOwnerCounter=pRevision(room,'owner'),sameOwnerGlobal=room.revision;parallel=await Promise.all(['Device A','Device B'].map(note=>api('owner',path(f)+'/'+room.id,'POST',{action:'prepare',revision:sameOwnerGlobal,participantRevision:sameOwnerCounter,operationKey:'own-device-'+note,preparation:{fighterIds:['fighter'],note}})));assert.equal(parallel.filter(value=>value.status===200).length,1);assert.equal(parallel.filter(value=>value.status===409).length,1);room=(await api('owner',path(f)+'/'+room.id)).room;assert.equal(pRevision(room,'owner'),sameOwnerCounter+1);assert.equal(room.participants.find(p=>p.userId==='source').preparation.note,'Prepared by source');
const readyGlobal=room.revision,atomicReadyBodies=['owner','source'].map(actor=>({action:'ready',ready:true,revision:readyGlobal,participantRevision:pRevision(room,actor),operationKey:'natural-ready-'+actor,preparation:{fighterIds:['fighter'],sideJobId:'',tacticIds:[],note:'Atomic ready '+actor}}));parallel=await Promise.all(['owner','source'].map((actor,index)=>api(actor,path(f)+'/'+room.id,'POST',atomicReadyBodies[index])));assert(parallel.every(value=>value.status===200),JSON.stringify(parallel.map(value=>({status:value.status,error:value.error}))));room=(await api('source',path(f)+'/'+room.id)).room;assert(room.participants.every(p=>p.ready&&p.preparation.note==='Atomic ready '+p.userId));const readyReplayRevision=room.revision;replay=await api('source',path(f)+'/'+room.id,'POST',atomicReadyBodies[1]);assert.equal(replay.status,200,replay.error);assert.equal(replay.room.revision,readyReplayRevision);result=await api('source',path(f)+'/'+room.id,'POST',{...atomicReadyBodies[1],preparation:{fighterIds:['fighter'],note:'Changed retry'}});assert.equal(result.status,409,result.error);
const staleSourceCounter=pRevision(room,'source'),staleReadyGlobal=room.revision;room=await action(f,room,'owner','setup',{setup:{scenarioName:'Changed shared mission'}});assert(pRevision(room,'source')>staleSourceCounter);assert(room.participants.every(p=>!p.ready));result=await api('source',path(f)+'/'+room.id,'POST',{action:'ready',ready:true,revision:staleReadyGlobal,participantRevision:staleSourceCounter,operationKey:'ready-stale-shared-setup',preparation:{fighterIds:['fighter'],note:'Obsolete setup'}});assert.equal(result.status,409,result.error);assert.equal((await api('source',path(f)+'/'+room.id)).room.participants.find(p=>p.userId==='source').ready,false);
console.log('PASS participant revision counters commute independent preparation and atomic readiness while protecting same-seat and shared-setup conflicts');

// A territory already committed to another active room cannot start a second campaign game.
f=fixture();room=await enter(f);room=await action(f,room,'owner','ready',{ready:true});room=await action(f,room,'source','ready',{ready:true});snapshot=read(f);snapshot.campaign.sessions.push({id:'lobby-session-other-active',lobbyRoomId:'other-active-room',territoryId:'stake',stage:'battle',status:'Active',participants:[]});sql.prepare('UPDATE shared_campaigns SET snapshot=?,revision=revision+1 WHERE id=?').run(JSON.stringify(snapshot),f.id);const occupiedSnapshot=clone(read(f)),occupiedRevision=revision(f);await action(f,room,'owner','start',{},409);assert.equal((await api('owner',path(f)+'/'+room.id)).room.status,'preparing');assert.deepEqual(read(f),occupiedSnapshot);assert.equal(revision(f),occupiedRevision);
f=fixture();room=await battle(f);const lockedSnapshot=clone(read(f)),lockedRevision=revision(f);for(const mutate of [candidate=>{candidate.campaign.territories[0].gangId='same';},candidate=>{candidate.campaign.territories=[];}]){const candidate=clone(lockedSnapshot);mutate(candidate);result=await api('owner','/campaigns/'+f.id,'PUT',{revision:lockedRevision,snapshot:candidate});assert.equal(result.status,403,result.error);for(const hideActiveBaseline of [false,true]){const beforeSnapshot=clone(lockedSnapshot),afterSnapshot=clone(lockedSnapshot);mutate(afterSnapshot);if(hideActiveBaseline){beforeSnapshot.campaign.sessions=[];afterSnapshot.campaign.sessions=[];}result=await api('owner','/campaigns/'+f.id+'/automation','POST',{operationKey:'active-stake-bypass-'+(++keySerial),label:'Change active stake',documentRevision:doc('owner').revision,expectedCampaignRevision:lockedRevision,before:beforeSnapshot,after:afterSnapshot});assert.equal(result.status,403,result.error);}assert.deepEqual(read(f),lockedSnapshot);assert.equal(revision(f),lockedRevision);}
snapshot=read(f);snapshot.campaign.territories[0].gangId='same';sql.prepare('UPDATE shared_campaigns SET snapshot=?,revision=revision+1 WHERE id=?').run(JSON.stringify(snapshot),f.id);room=await action(f,room,'owner','cancel');assert.equal(room.status,'cancelled');assert.equal(read(f).campaign.territories[0].gangId,'same');assert.equal(read(f).campaign.sessions.find(s=>s.id===room.sessionId).status,'Cancelled');assert.equal(read(f).campaign.battles.length,1);room=await create(f,'owner',{setup:{territoryId:'',deploymentId:'deployment-fixture',objectiveId:'objective-fixture',crewSelectionId:'crew-fixture'}});assert.equal(room.status,'invited');
console.log('PASS active stakes resist duplicate starts, external changes and hidden baselines; changed-stake cancellation releases both accounts');

