f=fixture();room=await enter(f);snapshot=read(f);snapshot.campaign.campaignSchedule={mode:'custom',stages:[{name:'Downtime',cycles:1}],completed:false,history:[]};sql.prepare('UPDATE shared_campaigns SET snapshot=?,revision=revision+1 WHERE id=?').run(JSON.stringify(snapshot),f.id);await action(f,room,'owner','ready',{ready:true},409);room=await action(f,room,'owner','cancel');assert.equal(room.status,'cancelled');assert.equal(read(f).campaign.sessions.length,1);
console.log('PASS known Downtime blocks new rooms and advancement while existing invitations can be cancelled');

// Start and mutual result agreement produce one linked session/report and one territory transfer.
