// Managed N26 crew draws implement the actual models behind the verified mission table.
function crewFixture(){const f=fixture();for(const actor of ['owner','source']){const d=doc(actor),base=d.state.gangs[0].fighters[0];d.state.gangs[0].fighters=Array.from({length:18},(_,i)=>({...clone(base),id:'unit-'+i,name:actor+' Unit '+i,loadouts:[{id:'set-'+i+'-a',active:true},{id:'set-'+i+'-b'}]}));d.state.gangs[0].fighters.push(...[{id:'recovering',inRecovery:true},{id:'captured-by',capturedBy:'enemy'},{id:'critical',injuries:[{id:'critical',rule_data:{critical:true}}]},{id:'retired',status:'Retired'},{id:'stashed',beastEquipmentStashed:true}].map(extra=>({...clone(base),...extra})));writeDoc(actor,d.state);}return f;}
async function crewRoom(f,crewSelectionId){let room=await create(f,'owner',{setup:{territoryId:'stake',deploymentId:'deployment-fixture',objectiveId:'objective-fixture',crewSelectionId,scenarioName:'Managed crew'}});return action(f,room,'source','accept');}
const crewRules=JSON.parse(fs.readFileSync(new URL('../dist/rules-data.json',import.meta.url))).scenarioEntries.filter(r=>r.edition_slug==='n26'&&r.source_verified&&r.table_type==='crew_selection'&&!r.gang_type_id);
const selfPrep=(room,actor)=>room.participants.find(p=>p.userId===actor).preparation;
{
 let calls=0;const originalRng=crypto.getRandomValues.bind(crypto);crypto.getRandomValues=array=>{calls++;return originalRng(array);};
 try{for(const rule of crewRules){const f=crewFixture(),before=originals();let room=await crewRoom(f,rule.id);for(const actor of ['owner','source']){const role=actor==='owner'?'attacker':'defender',spec=rule.rule_data.both||rule.rule_data[role];if(spec.chosen==='D3'){const countBefore=calls;room=await action(f,room,actor,'crew-plan');assert(calls>countBefore);const dice=clone(selfPrep(room,actor).crewPlan.dice),countAfter=calls;room=await action(f,room,actor,'crew-plan');assert.equal(calls,countAfter,'Reopening the count plan cannot reroll D3');assert.deepEqual(selfPrep(room,actor).crewPlan.dice,dice);}const chosen=spec.chosen==='D3'?selfPrep(room,actor).crewPlan.chosen:spec.chosen,chosenIds=Array.from({length:chosen},(_,i)=>'unit-'+i),countBefore=calls;room=await action(f,room,actor,'crew-draw',{selection:{chosenIds,loadouts:Object.fromEntries(chosenIds.map((id,i)=>[id,'set-'+i+'-b']))}});const prep=selfPrep(room,actor),plan=prep.crewPlan;assert.equal(plan.managed,true);assert.equal(plan.resolved,true);assert.equal(plan.role,role);assert.equal(plan.sourceCrewId,rule.id);assert.equal(plan.chosen,chosen);assert.equal(plan.random,spec.random==='D3'?plan.dice.random:spec.random||0);assert.equal(plan.reinforcements,spec.reinforcements||0);assert.equal(prep.crew.filter(c=>c.selection==='chosen').length,chosen);assert.equal(prep.crew.filter(c=>c.selection==='random').length,plan.random);assert.equal(prep.reinforcements.length,plan.reinforcements);assert.deepEqual(prep.fighterIds,prep.crew.map(c=>c.fighterId));assert.deepEqual(prep.crew.slice(0,chosen).map(c=>c.loadoutId),chosenIds.map((id,i)=>'set-'+i+'-b'));const all=[...prep.crew,...prep.reinforcements];assert.equal(new Set(all.map(c=>c.fighterId)).size,all.length);assert(all.every(c=>/^unit-\d+$/.test(c.fighterId)&&new RegExp('^set-'+c.fighterId.slice(5)+'-[ab]$').test(c.loadoutId)));if(plan.random||plan.reinforcements)assert(calls>countBefore,'Actual random deck calls secure randomness');else assert.equal(calls,countBefore,'Fixed all-chosen missions need no random draw');const stored=clone(prep),readsBefore=calls;for(let i=0;i<2;i++)assert.deepEqual(selfPrep((await api(actor,path(f)+'/'+room.id)).room,actor),stored);assert.equal(calls,readsBefore,'GET never redraws models or loadouts');assertOriginals(before);}}
 }finally{crypto.getRandomValues=originalRng;}
}
